head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/json2.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
scwin.vScrenID = "ULDSTF05813.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.vListProcsStatCd;
scwin.vAcptNo;
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.TR_JOB;
scwin.vSEG_CHG_TP_CD = "";
scwin.type = "";
scwin.pLogType = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_searchCode = function() {
    var arrCid = [{
        cid: "SEG_CHG_RSN_CD",
        cnm: "cmb_SEG_CHG_RSN_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SEG_CHG_RSN_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_read_sync = function() {
    var url = "/SegmentChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readSegment&inputMessageId=SEG_CHG_INOUT";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
};
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if ($c.stf.getObjectValue(cmb_BFCHG_SEG_TP_CD) == "") {
        $c.win.alert("[변경전] 항목을 선택하세요.");
        cmb_BFCHG_SEG_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SEG_TP_CD) == "") {
        $c.win.alert("[변경후] 항목을 선택하세요.");
        cmb_SEG_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_CHG_DD) == "") {
        $c.win.alert("[변경일]을 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if (vCurDate >= $c.stf.getObjectValue(edt_CHG_DD)) {
        $c.win.alert("[변경일]을 현재일이후로 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SEG_CHG_RSN_CD) == "") {
        $c.win.alert("[변경사유]를 선택하세요.");
        cmb_SEG_CHG_RSN_CD.focus();
        return false;
    }
    return true;
};
scwin.fn_duplicate_check = function() {
    var url = "/SegmentChange.do?method=checkDuplicate&inputMessageId=SEG_DUP_CHK_INOUT";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&CHG_DD=" + $c.stf.getObjectValue(edt_CHG_DD);
    dts_DUP_CHK.DataID = encodeURI(url);
    dts_DUP_CHK.Reset();
    return dts_DUP_CHK.getCellData(1, "DUP_CHK");
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (scwin.fn_duplicate_check() == 'Y') {
            $c.win.alert("[변경일]이 동일한 일자로 이미  입력되었습니다.");
            return;
        }
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_INSERT);
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_UPDATE);
    }
};
scwin.fn_delete = function() {
    if ($c.stf.getObjectValue(edt_APPROV_DDTM) != "") {
        $c.win.alert("승인처리가 완료된 후 삭제 할 수 없습니다.");
        return;
    }
    scwin.TR_JOB = 'D';
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.fn_trs(TR_JOB_DELETE);
};
scwin.fn_trs = function(jobType) {
    dts_Item.setCellData(1, "JOB_TYPE", jobType);
    dts_Item.setCellData(1, "LIST_BZ_TP_CD", LIST_BZ_TP_CD_236);
    dts_Item.setCellData(1, "SPOT_ISU_TRD_MKT_TP_CD", "2");
    if (jobType == "2") {
        //최초저장
        dts_Item.setCellData(1, "SEG_CHG_TP_CD", scwin.vSEG_CHG_TP_CD);
    }
    var vScrenProcTpCd;
    if (scwin.TR_JOB == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    trs_Save.Action = $c.lc.fn_encodeNSession("/SegmentChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveSegment");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item)";
    trs_Save.Post();
};
scwin.fn_revwr = function() {
    scwin.TR_JOB = '검토처리';
    scwin.pLogType = "1";
    var res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.TR_JOB));
    if (res) {
        scwin.fn_trslog('1');
    }
};
scwin.fn_approve = function() {
    if ($c.stf.getObjectValue(edt_REVW_DDTM) == "") {
        $c.win.alert("검토처리가 완료된 후 승인처리를 할 수 있습니다.");
        return;
    }
    scwin.TR_JOB = '승인처리';
    scwin.pLogType = "2";
    var res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.TR_JOB));
    if (res) {
        scwin.fn_trslog('2');
    }
};
scwin.fn_trslog = function(logTyp) {
    dts_Item.setCellData(1, "APPROV_TYPE", logTyp);
    dts_Item.setCellData(1, "REVWR_EMP_NO", js_emp_no);
    dts_Item.setCellData(1, "APPROV_EMP_NO", js_emp_no);
    dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);

    //alert('[dts_Item]'+dts_Item.text);
    trs_Log.Action = $c.lc.fn_encodeNSession("/SegmentChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveApprovLog");
    trs_Log.KeyName = "toinb_dataid4";
    trs_Log.KeyValue = "JSP(I:pInput=dts_Item)";
    trs_Log.Post();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_Search;
    fr_fn_list_sync();
};
scwin.fn_dscl = async function() {
    //수정된내용은 안내문작성에 미반영되도록 한번더 조회..
    scwin.fn_read_sync();
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_rel_eng, param_dts_dtl_all_eng) {
        arr[0] = "72091";
        arr[1] = dts_Item.getCellData(1, "BZ_PROCS_NO");
        arr[2] = dts_Item.getCellData(1, "ISUR_CD");
        arr[3] = 2;
        $c.stf.CopyDataSet(dts_Item, param_dts_mst);
        $c.stf.CopyDataSet(dts_Item, param_dts_mst_eng);
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 15;
    var hgt = 785 + 40;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.dts_Item_OnLoadError = function() {
    $c.stf.alert_error(dts_Item);
};
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    var chgDd = $c.stf.getObjectValue(edt_CHG_DD);
    if (chgDd > vCurDate) {
        buttonSet.setUpdateStatus();

        //090720-팀원은 컴토만, 팀장은 승인만 

        if (js_jobtitl == "03") {
            //팀원'03'

            btn_Revwr.src = "../img/btn_study.gif";
            btn_Revwr.setDisabled(false);
            btn_Approve.src = "../img/btn_approval_d.gif";
            btn_Approve.setDisabled(true);
            if ($c.stf.getObjectValue(edt_REVW_DDTM) != "") {
                btn_Revwr.src = "../img/btn_study_d.gif";
                btn_Revwr.setDisabled(true);
            }
            if ($c.stf.getObjectValue(edt_APPROV_DDTM) != "") {
                btn_Approve.src = "../img/btn_approval_d.gif";
                btn_Approve.setDisabled(true);
            }
        } else {
            //팀장 외

            btn_Revwr.src = "../img/btn_study_d.gif";
            btn_Revwr.setDisabled(true);
            btn_Approve.src = "../img/btn_approval.gif";
            btn_Approve.setDisabled(false);
            if ($c.stf.getObjectValue(edt_REVW_DDTM) != "") {
                btn_Revwr.src = "../img/btn_study_d.gif";
                btn_Revwr.setDisabled(true);
            }
            if ($c.stf.getObjectValue(edt_APPROV_DDTM) != "") {
                btn_Approve.src = "../img/btn_approval_d.gif";
                btn_Approve.setDisabled(true);
            }
        }
        //승인이 되면 수정,삭제버튼 비활성화
        if ($c.stf.getObjectValue(edt_APPROV_DDTM) != "") {
            buttonSet.setErrorStatus(); //disable 시킨다.

        }
    } else if (chgDd != "") {
        buttonSet.setErrorStatus(); //disable 시킨다.			
        if ($c.stf.getObjectValue(edt_REVW_DDTM) != "") {
            btn_Revwr.src = "../img/btn_study_d.gif";
            btn_Revwr.setDisabled(true);
        }
        if ($c.stf.getObjectValue(edt_APPROV_DDTM) != "") {
            btn_Approve.src = "../img/btn_approval_d.gif";
            btn_Approve.setDisabled(true);
        }
    }
    if ($c.stf.getObjectValue(edt_APPROV_DDTM) == "") {
        btn_Dscl.src = "../img/btn_make_info_d.gif";
        btn_Dscl.setDisabled(true);
    } else {
        btn_Dscl.src = "../img/btn_make_info.gif";
        btn_Dscl.setDisabled("");
    }
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_parentRefresh();
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_read_sync();
    }
};
scwin.trs_Log_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.TR_JOB));
    $c.stf.alert_error(trs_Log);
};
scwin.trs_Log_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.TR_JOB));
    scwin.fn_parentRefresh();
    scwin.fn_read_sync();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Revwr_onclick = function() {
    scwin.fn_revwr();
};
scwin.btn_Approve_onclick = function() {
    scwin.fn_approve();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Item);
    $c.elw.fn_searchCode();
    var parentWin = $c.frame.path("../");
    var dstOjb = parentWin.dts_List_2;
    var row = dstOjb.getFocusedRowIndex();
    scwin.vBzProcsNo = dstOjb.getCellData(row, "BZ_PROCS_NO");
    scwin.vAcptNo = dstOjb.getCellData(row, "ACPT_NO");
    scwin.vListProcsStatCd = dstOjb.getCellData(row, "LIST_PROCS_STAT_CD");
    scwin.vSEG_CHG_TP_CD = dstOjb.getCellData(row, "SEG_CHG_TP_CD");
    scwin.vSPOT_ISU_TRD_MKT_TP_CD = '2';
    //setObjectValue(txb_ISUR_NM, dstOjb.NameString(row,"COM_ABBRV"));
    //setObjectValue(txb_ISUR_CD, dstOjb.NameString(row,"ISUR_CD"));

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정	
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성

    if (scwin.vListProcsStatCd == "10") {
        //미처리
        buttonSet.setInsertStatus();
        btn_Revwr.src = "../img/btn_study_d.gif";
        btn_Revwr.setDisabled(true);
        btn_Approve.src = "../img/btn_approval_d.gif";
        btn_Approve.setDisabled(true);
        btn_Dscl.src = "../img/btn_make_info_d.gif";
        btn_Dscl.setDisabled(true);
    } else {
        //090720-팀원은 컴토만, 팀장은 승인만 
        if (js_jobtitl == "03") {
            //팀원'03'
            btn_Revwr.src = "../img/btn_study.gif";
            btn_Revwr.setDisabled(false);
            btn_Approve.src = "../img/btn_approval_d.gif";
            btn_Approve.setDisabled(true);
        } else {
            btn_Revwr.src = "../img/btn_study_d.gif";
            btn_Revwr.setDisabled(true);
            btn_Approve.src = "../img/btn_approval.gif";
            btn_Approve.setDisabled(false);
        }
    }
    scwin.fn_read_sync();
};
scwin.img_CHG_DD_onclick = function() {
    popUpCalendar2(edt_CHG_DD);
};
